//! `cargo xtask docs`: the generated reference pages in `docs/reference/` and the `llms.txt`
//! index (FR-46, FR-51), from the same sources the MCP server and the crates use. `--check`
//! fails if any of them is out of date (CI).

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

use serde_json::Value;

/// Where the raw Markdown lives online, for `llms.txt`.
const RAW: &str = "https://raw.githubusercontent.com/hardlessdev/hardless/main";

const GENERATED: &str =
    "<!-- Generated by `cargo xtask docs` from the source code. Do not edit; CI checks it. -->\n\n";

/// What each device kind is, for the device reference.
const KINDS: [(&str, &str); 4] = [
    (
        "printer-escpos",
        "An ESC/POS receipt printer. It parses each job into a command AST, answers `DLE EOT` status requests, kicks an attached cash drawer and renders receipts at 58 or 80 mm. `transport` says how the app reaches it: Web Serial (`serial`), WebUSB (`usb`) or the HTTP printer endpoints (`http`).",
    ),
    (
        "cash-drawer",
        "A cash drawer plugged into a printer's drawer-kick connector. It opens when the printer gets a kick on its pin (ESC/POS `ESC p`, an ePOS `pulse`, a WebPRNT drawer command), and closes by hand or after `autoCloseMs`. The printer reports it in its status.",
    ),
    (
        "scanner-wedge",
        "A keyboard-wedge barcode scanner: it types each scan into the page's focused field, a few milliseconds per key, then a terminator key.",
    ),
    (
        "nfc-reader",
        "An NFC reader with virtual cards, for Web NFC (`NDEFReader`). A tap puts a card on the reader for `presenceMs` and reads it; while it is there the app can write to it or lock it. The reader remembers cards and what was written to them.",
    ),
];

fn heading_title(markdown: &str) -> String {
    markdown
        .lines()
        .find_map(|l| l.strip_prefix("# "))
        .unwrap_or("Untitled")
        .trim()
        .to_owned()
}

/// The first sentence of the first paragraph after the title.
fn summary(markdown: &str) -> String {
    let body = markdown
        .lines()
        .skip_while(|l| !l.starts_with("# "))
        .skip(1)
        .skip_while(|l| l.trim().is_empty() || l.starts_with("<!--"))
        .take_while(|l| !l.trim().is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    let sentence = body.split(". ").next().unwrap_or_default().trim();
    let sentence = sentence.trim_end_matches('.');
    // Links read badly in an index: keep their text.
    let mut out = String::new();
    let mut rest = sentence;
    while let Some(start) = rest.find('[') {
        out.push_str(&rest[..start]);
        let after = &rest[start + 1..];
        match (after.find("]("), after.find(')')) {
            (Some(mid), Some(end)) if mid < end => {
                out.push_str(&after[..mid]);
                rest = &after[end + 1..];
            }
            _ => {
                out.push('[');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    format!("{}.", out.trim())
}

fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

/// A JSON Schema type in a few words.
fn type_of(schema: &Value) -> String {
    if let Some(value) = schema.get("const") {
        return match value.as_str() {
            Some(text) => format!("`{text}`"),
            None => format!("`{value}`"),
        };
    }
    if let Some(values) = schema["enum"].as_array() {
        return values
            .iter()
            .map(|v| format!("`{v}`"))
            .collect::<Vec<_>>()
            .join(", ");
    }
    if let Some(r) = schema["$ref"].as_str() {
        return r.rsplit('/').next().unwrap_or(r).to_owned();
    }
    match &schema["type"] {
        Value::String(t) => t.clone(),
        Value::Array(types) => types
            .iter()
            .filter_map(Value::as_str)
            .filter(|t| *t != "null")
            .collect::<Vec<_>>()
            .join(" or "),
        _ => schema["anyOf"]
            .as_array()
            .or(schema["oneOf"].as_array())
            .map(|options| {
                options
                    .iter()
                    .map(type_of)
                    .filter(|t| t != "null")
                    .collect::<Vec<_>>()
                    .join(" or ")
            })
            .unwrap_or_else(|| "any".to_owned()),
    }
}

/// A JSON Schema's properties as a Markdown table, resolving `$defs` enums.
fn properties_table(schema: &Value) -> String {
    let Some(props) = schema["properties"].as_object() else {
        return "No settings.\n".to_owned();
    };
    let defs = schema["$defs"].as_object().cloned().unwrap_or_default();
    let required: Vec<&str> = schema["required"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect();
    let mut out = String::from("| Field | Type | Default | Meaning |\n| --- | --- | --- | --- |\n");
    for (name, prop) in props {
        let resolved = prop["$ref"]
            .as_str()
            .and_then(|r| r.rsplit('/').next())
            .and_then(|name| defs.get(name))
            .unwrap_or(prop);
        let mut kind = type_of(resolved);
        if kind == "any" {
            kind = type_of(prop);
        }
        let default = match prop.get("default").or(resolved.get("default")) {
            Some(Value::Null) | None if !required.contains(&name.as_str()) => "none".to_owned(),
            Some(v) => format!("`{v}`"),
            None if required.contains(&name.as_str()) => "required".to_owned(),
            None => "none".to_owned(),
        };
        let meaning = prop["description"]
            .as_str()
            .or(resolved["description"].as_str())
            .unwrap_or_default();
        out.push_str(&format!(
            "| `{name}` | {} | {default} | {} |\n",
            cell(&kind),
            cell(meaning)
        ));
    }
    out
}

fn devices_page() -> String {
    let mut registry = hardless_core::Registry::new(hardless_core::FakeClock::new());
    let _ = hardless_devices::register_all(&mut registry);
    let mut out = format!(
        "# Device reference\n\n{GENERATED}Every device kind Hardless emulates, its settings (the `config` of `POST /api/v1/devices`, the config file or the Playwright fixture) and the faults it supports. Faults are described in the [fault reference](faults.md).\n"
    );
    for (kind, about) in KINDS {
        let Some(plugin) = registry.plugin(kind) else {
            continue;
        };
        let schema = serde_json::to_value(plugin.config_schema()).unwrap_or(Value::Null);
        let faults = plugin
            .faults()
            .iter()
            .map(|f| format!("`{f}`"))
            .collect::<Vec<_>>()
            .join(", ");
        out.push_str(&format!(
            "\n## `{kind}`\n\n{about}\n\n{}\nFaults: {faults}.\n",
            properties_table(&schema)
        ));
    }
    out
}

fn tools_page() -> String {
    let mut out = format!(
        "# MCP tool reference\n\n{GENERATED}The tools of the Hardless MCP server (`hardless mcp`, or `/mcp` on the server); see [Using Hardless from an AI agent](../agents.md). Every tool also has an output schema; receipt tools add a PNG image block.\n"
    );
    for tool in hardless_mcp::tool_list() {
        let name = tool["name"].as_str().unwrap_or_default();
        let description = tool["description"].as_str().unwrap_or_default();
        let hints = match (
            tool["annotations"]["readOnlyHint"].as_bool(),
            tool["annotations"]["destructiveHint"].as_bool(),
        ) {
            (Some(true), _) => " Read-only.",
            (_, Some(true)) => " Destructive.",
            _ => "",
        };
        out.push_str(&format!(
            "\n## `{name}`\n\n{}{hints}\n\n{}",
            description.trim(),
            properties_table(&tool["inputSchema"])
        ));
    }
    out
}

/// The generated pages, by path.
pub fn generated() -> BTreeMap<&'static str, String> {
    BTreeMap::from([
        ("docs/reference/devices.md", devices_page()),
        (
            "docs/reference/faults.md",
            hardless_mcp::docs::faults().replacen("\n\n", &format!("\n\n{GENERATED}"), 1),
        ),
        (
            "docs/reference/escpos-commands.md",
            hardless_mcp::docs::escpos_commands().replacen("\n\n", &format!("\n\n{GENERATED}"), 1),
        ),
        (
            "docs/reference/http-dialects.md",
            hardless_mcp::docs::http_dialects().replacen("\n\n", &format!("\n\n{GENERATED}"), 1),
        ),
        ("docs/reference/mcp-tools.md", tools_page()),
    ])
}

/// The hand-written pages `llms.txt` lists, in order, and the sections they go in.
const PAGES: [(&str, &str); 6] = [
    ("Docs", "docs/quickstart.md"),
    ("Docs", "docs/testing.md"),
    ("Docs", "docs/agents.md"),
    ("Docs", "docs/rest-api.md"),
    ("Docs", "docs/plugins.md"),
    ("Docs", "AGENTS.md"),
];

/// `llms.txt` (llmstxt.org): a short summary and links to every doc page, with each page's
/// title and first sentence.
pub fn llms_txt(root: &Path, generated: &BTreeMap<&'static str, String>) -> Result<String, String> {
    let mut out = String::from(
        "# Hardless\n\n> Hardless emulates POS hardware (receipt printers, cash drawers, barcode scanners and NFC readers) so web apps and PWAs can be built and tested without the devices. It replaces the browser APIs an app uses (Web Serial, WebUSB, Web NFC, keyboard input) or answers its HTTP printer calls, renders receipts, and lets tests and AI agents inject faults.\n\nThe `hardless` binary runs the server: dashboard at http://localhost:8080, REST API at /api/v1, browser bridge at /bridge, MCP at /mcp. Apps connect through `@hardless/shim-web` (or the Chrome extension); tests use `@hardless/playwright`; agents use `hardless mcp`.\n",
    );
    let mut section = "";
    for (name, path) in PAGES {
        let text =
            fs::read_to_string(root.join(path)).map_err(|e| format!("reading {path}: {e}"))?;
        if section != name {
            out.push_str(&format!("\n## {name}\n\n"));
            section = name;
        }
        out.push_str(&format!(
            "- [{}]({RAW}/{path}): {}\n",
            heading_title(&text),
            summary(&text)
        ));
    }
    out.push_str("\n## Reference\n\n");
    for (path, text) in generated {
        out.push_str(&format!(
            "- [{}]({RAW}/{path}): {}\n",
            heading_title(text),
            summary(text)
        ));
    }
    out.push_str(&format!(
        "\n## Optional\n\n- [Product requirements]({RAW}/docs/PRD.md): the full specification.\n- [Decisions]({RAW}/docs/decisions.md): every choice and deviation from the specification.\n"
    ));
    Ok(out)
}

/// Every Markdown page under `docs/` that `llms.txt` must list (all but the spec, the
/// decision log and local files).
pub fn unlisted(root: &Path) -> Vec<String> {
    let listed: Vec<&str> = PAGES.iter().map(|(_, p)| *p).collect();
    let mut missing = Vec::new();
    if let Ok(entries) = fs::read_dir(root.join("docs")) {
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let path = format!("docs/{name}");
            if name.ends_with(".md")
                && !["PRD.md", "decisions.md", "HANDOFF.md"].contains(&name.as_str())
                && !listed.contains(&path.as_str())
            {
                missing.push(path);
            }
        }
    }
    missing
}
